      if (pdoc.querySelector(`#${ID} .toggle-btn[data-id="${config.id}"]`)) return;
      const grid = findGridByExistingButton(anchorId);
      if (!grid) {
        console.warn("[orb] ensurePresetButton: 找不到插入锚点", anchorId, config.kw);
